#include <zephyr/device.h>
#include <zephyr/drivers/retention.h>
#include <zephyr/kernel.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(retention, CONFIG_RETENTION_LOG_LEVEL);

#ifdef CONFIG_RETENTION_GENERIC

struct retention_generic_data {
	/* No runtime data needed for generic driver */
};

struct retention_generic_config {
	/* No configuration data needed for generic driver */
};

static int retention_generic_init(const struct device *dev)
{
	ARG_UNUSED(dev);

	LOG_DBG("Generic retention driver initialized");
	return 0;
}

static int retention_generic_read(const struct device *dev, off_t addr, void *data, size_t len)
{
	ARG_UNUSED(dev);

	LOG_ERR("Generic retention driver does not support read operations");
	return -ENOTSUP;
}

static int retention_generic_write(const struct device *dev, off_t addr, const void *data, size_t len)
{
	ARG_UNUSED(dev);

	LOG_ERR("Generic retention driver does not support write operations");
	return -ENOTSUP;
}

static int retention_generic_clear(const struct device *dev, off_t addr, size_t len)
{
	ARG_UNUSED(dev);

	LOG_ERR("Generic retention driver does not support clear operations");
	return -ENOTSUP;
}

static const struct retention_driver_api retention_generic_api = {
	.read = retention_generic_read,
	.write = retention_generic_write,
	.clear = retention_generic_clear,
};

/*
 * The generic retention driver is a placeholder. It does not directly manage
 * any retention memory. Its purpose is to provide a default retention device
 * if CONFIG_RETENTION_GENERIC is enabled, allowing applications to use the
 * retention API even if no specific hardware retention driver is available.
 * Operations on this generic device will return -ENOTSUP.
 *
 * This device is only defined if CONFIG_RETENTION_GENERIC is enabled.
 */
DEVICE_DEFINE(retention_generic, CONFIG_RETENTION_GENERIC_LABEL, retention_generic_init,
	      NULL, &retention_generic_data, &retention_generic_config, POST_KERNEL,
	      CONFIG_KERNEL_INIT_PRIORITY_DEVICE, &retention_generic_api);

#endif /* CONFIG_RETENTION_GENERIC */

/*
 * The retention API functions are implemented as wrappers around the device
 * API. These functions are only compiled if CONFIG_RETENTION is enabled.
 */
#ifdef CONFIG_RETENTION

const struct device *retention_get_default_device(void)
{
#ifdef CONFIG_RETENTION_GENERIC
	return DEVICE_GET(retention_generic);
#else
	/* If no generic driver, and no other specific driver is configured as default,
	 * this might return NULL or a specific board-defined default.
	 * For now, return NULL if no generic driver and no other default is explicitly set.
	 */
	return NULL;
#endif
}

int retention_read(const struct device *dev, off_t addr, void *data, size_t len)
{
	if (dev == NULL) {
		return -EINVAL;
	}

	const struct retention_driver_api *api = (const struct retention_driver_api *)dev->api;

	if (api->read == NULL) {
		return -ENOTSUP;
	}

	return api->read(dev, addr, data, len);
}

int retention_write(const struct device *dev, off_t addr, const void *data, size_t len)
{
	if (dev == NULL) {
		return -EINVAL;
	}

	const struct retention_driver_api *api = (const struct retention_driver_api *)dev->api;

	if (api->write == NULL) {
		return -ENOTSUP;
	}

	return api->write(dev, addr, data, len);
}

int retention_clear(const struct device *dev, off_t addr, size_t len)
{
	if (dev == NULL) {
		return -EINVAL;
	}

	const struct retention_driver_api *api = (const struct retention_driver_api *)dev->api;

	if (api->clear == NULL) {
		return -ENOTSUP;
	}

	return api->clear(dev, addr, len);
}

#endif /* CONFIG_RETENTION */
